<!DOCTYPE html>
<html lang="vi-VN">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=JetBrains+Mono:wght@400;700&display=swap" rel="stylesheet">
    <title>Lịch Trình Dệt Mộng</title>
    <style>
        :root {
            --bg-app: #1e1e2e;
            --bg-header: #151521;
            --bg-card: #252538;
            --bg-scroller-item: #2a2a3c;
            --bg-scroller-active: linear-gradient(135deg, #ff7eb3, #a78bfa);

            --text-primary: #ffffff;
            --text-secondary: #9ca3af;
            --text-inverse: #ffffff;
            --text-desc: #e4e4e7;

            --border-color: rgba(255, 126, 179, 0.4);
            --separator-color: #3f3f5a;

            --shadow-soft: 0 4px 15px rgba(0, 0, 0, 0.4);
            --shadow-card: 0 4px 10px rgba(0, 0, 0, 0.3);
            --shadow-active: 0 8px 20px rgba(255, 126, 179, 0.3);

            --accent-world: #a78bfa;
            --accent-major: #fbbf24;
            --accent-user: #38bdf8;
            --accent-char: #ff85b3;
        }

        body { margin: 0; padding: 0; background: transparent !important; }

        .calendar-app {
            font-family: 'Nunito', system-ui, -apple-system, sans-serif;
            background: var(--bg-app);
            color: var(--text-primary);
            border-radius: 12px;
            width: 100%;
            max-width: 100%;
            margin: 15px 0;
            box-shadow: var(--shadow-soft);
            border: 1px solid var(--border-color);
            display: flex;
            flex-direction: column;
            transition: all 0.3s ease;
            position: relative;
        }

        .cal-header {
            padding: 20px 20px 12px; display: flex; flex-direction: column;
            background: var(--bg-header); border-bottom: 1px solid var(--separator-color); 
        }

        .cal-title { font-family: 'Georgia', serif; font-size: 1.4rem; font-weight: 800; letter-spacing: 0.5px; margin-bottom: 4px; color: var(--accent-char); }
        .cal-subtitle { font-family: 'JetBrains Mono', monospace; font-size: 0.75rem; color: var(--accent-world); border: 1px solid var(--accent-world); padding: 2px 6px; border-radius: 4px; width: fit-content; text-transform: uppercase; letter-spacing: 1px; }

        .compose-panel { padding: 16px 20px; display: flex; gap: 12px; align-items: flex-start; justify-content: space-between; background: var(--bg-header); border-bottom: 1px dashed var(--separator-color); }
        .compose-copy { min-width: 0; flex: 1; }

        .compose-title { display: flex; align-items: center; gap: 8px; font-size: 0.95rem; font-weight: 800; color: var(--text-primary); }
        .selected-count { min-width: 24px; padding: 2px 8px; border-radius: 6px; background: rgba(255, 126, 179, 0.15); color: var(--accent-char); font-weight: 800; font-size: 0.8rem; border: 1px solid rgba(255,126,179,0.3); }

        .compose-hint { margin-top: 8px; font-size: 0.85rem; line-height: 1.5; color: var(--text-secondary); font-family: 'JetBrains Mono', monospace;}

        .compose-actions { display: flex; flex-direction: column; gap: 10px; flex-shrink: 0; }

        .compose-action-btn {
            min-width: 110px; padding: 8px 14px; border: 1px solid var(--separator-color); border-radius: 8px;
            background: var(--bg-card); color: var(--text-primary); font-size: 0.85rem; font-weight: 700;
            cursor: pointer; transition: all 0.2s ease; font-family: 'Nunito', sans-serif;
        }

        .compose-action-btn:hover:not(:disabled) { transform: translateY(-2px); border-color: var(--accent-char); color: var(--accent-char); }
        .compose-action-btn:disabled { cursor: not-allowed; opacity: 0.4; }

        .compose-action-btn.primary { background: var(--bg-scroller-active); color: #fff; border-color: transparent; }
        .compose-action-btn.primary:hover:not(:disabled) { box-shadow: var(--shadow-active); color: #fff; }

        /* === SỬA DATE SCROLLER === */
        .date-scroller {
            display: flex;
            overflow-x: hidden;
            padding: 12px 16px;
            gap: 8px;
            scrollbar-width: none;
            border-bottom: 1px solid var(--separator-color);
        }
        .date-scroller::-webkit-scrollbar { display: none; }

        /* Các ô tự giãn đều, không cố định width */
        .date-card {
            flex: 1 1 0;
            min-width: 0;
            height: 90px;
            background: var(--bg-scroller-item);
            border-radius: 10px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s ease;
            position: relative;
            border: 1px solid var(--separator-color);
            color: var(--text-primary);
            padding: 0 4px;
            box-sizing: border-box;
        }

        .date-card.active {
            background: var(--bg-scroller-active);
            color: #fff;
            border-color: transparent;
            box-shadow: var(--shadow-active);
            transform: translateY(-4px);
        }

        /* Thứ (THỨ HAI, CHỦ NHẬT...) */
        .date-card .day-name {
            font-size: 0.6rem;
            font-weight: 800;
            text-transform: uppercase;
            white-space: nowrap;
            letter-spacing: -0.3px;
            opacity: 0.85;
            margin-bottom: 4px;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 100%;
        }

        /* Số ngày to */
        .date-card .day-num {
            font-size: 1.3rem;
            font-weight: 800;
            font-family: 'JetBrains Mono', monospace;
            line-height: 1;
        }

        /* Tháng nhỏ bên dưới */
        .date-card .day-month {
            font-size: 0.65rem;
            font-weight: 700;
            font-family: 'JetBrains Mono', monospace;
            opacity: 0.7;
            margin-top: 2px;
        }

        .event-dots { display: flex; gap: 4px; margin-top: 6px; height: 5px; align-items: center; }
        .dot { width: 5px; height: 5px; border-radius: 50%; background-color: var(--text-secondary); opacity: 0.4; }
        .date-card.active .dot { background-color: #fff; opacity: 1; box-shadow: 0 0 4px #fff; }

        .event-list { padding: 20px; min-height: 280px; background-color: transparent; }

        .event-details-card {
            margin-bottom: 16px; background: var(--bg-card); border-radius: 10px; box-shadow: var(--shadow-card);
            position: relative; border: 1px solid var(--separator-color); transition: all 0.2s ease;
        }

        .event-details-card::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; background: var(--accent-char); z-index: 1; border-radius: 10px 0 0 10px; }
        .event-details-card[open] { border-color: rgba(255, 126, 179, 0.3); }

        .event-details-card.selected { border-color: var(--accent-char); transform: translateX(4px); }

        .event-summary { list-style: none; cursor: pointer; padding: 15px 15px 15px 20px; position: relative; display: flex; flex-direction: column; gap: 6px; transition: background-color 0.2s; }
        .event-summary::-webkit-details-marker { display: none; }
        .event-summary:hover { background-color: rgba(255, 255, 255, 0.02); }

        .arrow-icon { position: absolute; right: 15px; top: 15px; width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; transition: transform 0.3s ease; opacity: 0.5; font-size: 18px; font-weight: 800; color: var(--text-primary); }
        .event-details-card[open] .arrow-icon { transform: rotate(90deg); opacity: 1; color: var(--accent-char); }

        .event-meta-row { display: flex; justify-content: space-between; align-items: center; font-size: 0.75rem; font-weight: 800; letter-spacing: 0.5px; margin-bottom: 2px; padding-right: 28px; font-family: 'JetBrains Mono', monospace; text-transform: uppercase; }
        .event-meta-left { display: inline-flex; align-items: center; gap: 10px; min-width: 0; }

        .event-select-btn {
            flex-shrink: 0; padding: 4px 10px; border-radius: 6px; border: 1px solid var(--separator-color); background: var(--bg-app); color: var(--text-primary); font-size: 0.75rem; font-weight: 800; cursor: pointer; transition: all 0.2s ease; font-family: 'Nunito', sans-serif;
        }
        .event-select-btn:hover { border-color: var(--accent-char); color: var(--accent-char); background: rgba(255,126,179,0.1); }
        .event-select-btn.selected { background: var(--bg-scroller-active); color: #fff; border-color: transparent; }

        .event-title { font-size: 1.05rem; font-weight: 800; line-height: 1.5; color: var(--text-primary); padding-right: 28px; word-wrap: break-word; overflow-wrap: break-word; white-space: normal; }
        .event-loc { font-size: 0.85rem; color: var(--text-secondary); display: flex; align-items: center; gap: 6px; margin-top: 4px; font-weight: 600; word-wrap: break-word; }

        .event-description-wrapper { padding: 0 20px 20px 20px; border-top: 1px dashed var(--separator-color); margin-top: 6px; padding-top: 16px; opacity: 0; animation: slideDownFade 0.3s ease forwards; }
        .event-description { font-size: 0.95rem; color: var(--text-desc); line-height: 1.7; word-wrap: break-word; overflow-wrap: break-word; white-space: pre-wrap; text-align: left; }

