            white-space: pre-wrap; border: 1px solid #2d2d44; font-family: 'JetBrains Mono', Consolas, monospace;
            word-wrap: break-word; overflow-wrap: break-word; box-shadow: inset 0 2px 5px rgba(0,0,0,0.5);
        }
        .event-npc-note::before { content: '>_ Tawa lén nhìn thấy: '; font-weight: 800; color: var(--accent-world); display: block; margin-bottom: 4px; }

        @keyframes slideDownFade { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }

        .type-world::before { background: var(--accent-world); } .type-world .event-meta-row { color: var(--accent-world); }
        .type-major::before { background: var(--accent-major); } .type-major .event-meta-row { color: var(--accent-major); }
        .type-user::before { background: var(--accent-user); } .type-user .event-meta-row { color: var(--accent-user); }
