<!DOCTYPE html>
<html lang="vi-VN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;600;700&family=Cormorant+Garamond:ital,wght@0,300;0,400;0,600;1,300;1,400&display=swap">
</head>
<body>
<div class="ink-header" data-tags="$4" data-meta="$5">
<style>
/* ============================================================
   INK HEADER — v4 (Mod Giao Diện Tối/Sáng Thông Minh)
   Chữ sáng hơn · Hiệu ứng thời tiết nhẹ · Chỉ transform+opacity
   ============================================================ */
.ink-header{
  --ink-accent:#d4b483;
  --ink-text:#e8e2d8;
  --ink-sub:rgba(232,226,216,.52);
  --ink-line:rgba(232,226,216,.15);
  --ink-tag-bg:rgba(255,255,255,.07);
  --ink-icon:#aaa;
  --ink-glow:transparent;
  --ink-title-color:#f0ebe2;
  --ink-fs:1;

  /* 🌸 Biến màu nền (Mặc định: Tối) */
  --ink-bg: rgba(20, 18, 15, 0.85); 

  /* 🌸 Biến màu thời tiết (Ban đêm - Màu sáng mờ ảo) */
  --wx-rain: rgba(160,195,230,.65);
  --wx-snow: rgba(220,228,245,.8);
  --wx-sun1: rgba(255,230,110,.13);
  --wx-sun2: rgba(255,235,140,.18);
  --wx-fog1: rgba(200,200,210,.1);
  --wx-fog2: rgba(200,200,210,.13);
  --wx-wind: rgba(210,210,210,.4);

  font-family:'Cormorant Garamond','Noto Serif SC',serif;
  color:var(--ink-text);
  background:transparent; /* Chuyển màu nền xuống lớp ::after để không lỗi animation */
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  max-width:1200px;margin:20px auto;padding:32px 20px 24px;
  position:relative;text-align:center;overflow:hidden;
  animation:inkIn .8s ease;
}

/* 🌸 Lớp nền Glassmorphism siêu xịn tách biệt (Fix lỗi mất thời tiết) */
.ink-header::after {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--ink-bg);
  backdrop-filter: blur(8px);
  z-index: 0;
  transition: background 0.4s ease;
}

.ink-header *{box-sizing:border-box;margin:0;padding:0}

.ink-header::before{
  content:'';position:absolute;top:0;left:15%;right:15%;
  height:1px;background:linear-gradient(90deg,transparent,var(--ink-line),transparent);z-index:6;
}

/* ── Chế độ sáng (day) ── */
.ink-header.day{
  --ink-accent:#5a3e28;
  --ink-text:#1e1a16;
  --ink-sub:rgba(30,26,22,.5);
  --ink-line:rgba(30,26,22,.14);
  --ink-tag-bg:rgba(0,0,0,.05);
  --ink-icon:#666;
  --ink-title-color:#1e1a16;

  /* 🌸 Biến màu nền ban ngày */
  --ink-bg: rgba(248, 245, 240, 0.9); 

  /* 🌸 Biến màu thời tiết (Ban ngày - Tự động sẫm màu để nổi bật trên nền sáng) */
  --wx-rain: rgba(80,120,180,.4);
  --wx-snow: rgba(140,160,190,.7);
  --wx-sun1: rgba(255,160,50,.08);
  --wx-sun2: rgba(255,180,70,.12);
  --wx-fog1: rgba(120,120,130,.06);
  --wx-fog2: rgba(120,120,130,.09);
  --wx-wind: rgba(120,120,120,.25);
}

/* ── Vùng thời tiết ── */
.ink-weather-fx{
  position:absolute;inset:0;z-index:1;overflow:hidden;pointer-events:none;
}

/* ============================================================
   HIỆU ỨNG THỜI TIẾT — Đã tích hợp Biến Đổi Màu Sắc Thông Minh
   ============================================================ */

/* --- Mưa --- */
.wx-rain{
  position:absolute;top:-32px;
  width:1px;
  background:linear-gradient(to bottom,transparent,var(--wx-rain),transparent);
  animation:wxRain linear infinite;
}
@keyframes wxRain{
  from{transform:translateY(0)}
  to  {transform:translateY(calc(100% + 400px))}
}

/* --- Tuyết --- */
.wx-snow{
  position:absolute;top:-12px;
  border-radius:50%;
  background:var(--wx-snow);
  animation:wxSnow linear infinite;
}
@keyframes wxSnow{
  from{transform:translate(0,0) rotate(0deg)}
  to  {transform:translate(var(--dx,12px),calc(100% + 300px)) rotate(360deg)}
}

/* --- Nắng: vệt sáng xéo, mỏng, pulse opacity --- */
.wx-sun-beam{
  position:absolute;top:0;bottom:0;
  background:linear-gradient(108deg,
    transparent 0%,
    var(--wx-sun1) 48%,
    var(--wx-sun2) 50%,
    var(--wx-sun1) 52%,
    transparent 100%);
  animation:wxBeam ease-in-out infinite;
}
@keyframes wxBeam{
  0%,100%{opacity:0;transform:translateX(-8px)}
  50%    {opacity:1;transform:translateX(8px)}
}

/* Điểm lấp lánh — nắng & sao */
.wx-dot{
  position:absolute;
  border-radius:50%;
  background:rgba(255,248,190,.95);
  animation:wxDot ease-in-out infinite;
}
.wx-dot.star{background:rgba(255,255,255,.9)}
@keyframes wxDot{
  0%,100%{opacity:0;transform:scale(.3)}
  45%,55%{opacity:1;transform:scale(1)}
}

/* --- Sương mù / mây --- */
.wx-fog{
  position:absolute;left:-35%;
  border-radius:60px;
  background:linear-gradient(90deg,
    transparent 0%,
    var(--wx-fog1) 30%,
    var(--wx-fog2) 50%,
    var(--wx-fog1) 70%,
    transparent 100%);
  animation:wxFog linear infinite;
}
@keyframes wxFog{
  from{transform:translateX(0)}
  to  {transform:translateX(160%)}
}

/* --- Gió --- */
.wx-wind{
  position:absolute;left:0;right:0;height:1px;
  background:linear-gradient(90deg,
    transparent 0%,
    var(--wx-wind) 20%,
    var(--wx-wind) 80%,
    transparent 100%);
  animation:wxWind ease-in-out infinite;
}
@keyframes wxWind{
  0%  {transform:translate(-110%,-0px);opacity:0}
  15%,85%{opacity:1}
  100%{transform:translate(110%,8px);opacity:0}
}

/* --- Chớp --- */
.wx-flash{
  position:absolute;inset:0;
  background:rgba(210,225,255,0);
  animation:wxFlash ease infinite;
  pointer-events:none;
}
@keyframes wxFlash{
  0%,85%,89%,93%,100%{background:rgba(210,225,255,0)}
  86%{background:rgba(210,225,255,.16)}
  87%{background:rgba(210,225,255,0)}
  91%{background:rgba(210,225,255,.24)}
  92%{background:rgba(210,225,255,.04)}
}

/* ============================================================
   LAYOUT & CHỮ
   ============================================================ */
.ink-content{position:relative;z-index:5}

.ink-chapter{
  font-family:'Cormorant Garamond',serif;
  font-size:calc(12px * var(--ink-fs));
  letter-spacing:5px;text-transform:uppercase;
  color:var(--ink-accent);margin-bottom:6px;opacity:.8;
  transition:font-size .25s;
}
.ink-title{
  font-family:'Noto Serif SC',serif;
  font-size:calc(1.85em * var(--ink-fs));
  font-weight:600;letter-spacing:2px;line-height:1.35;
  margin:8px 0 6px;
  color:var(--ink-title-color);
  text-shadow:0 1px 12px rgba(0,0,0,.25);
  transition:font-size .25s,color .4s;
}
.ink-subtitle{
  font-size:calc(.88em * var(--ink-fs));
  font-weight:300;font-style:italic;
  color:var(--ink-sub);letter-spacing:1px;margin-bottom:16px;
  transition:font-size .25s;
}
.ink-deco-line{
  width:44%;height:1px;margin:0 auto 14px;
  background:linear-gradient(90deg,transparent,var(--ink-line),transparent);
  position:relative;
}
.ink-deco-line::after{
  content:'◆';position:absolute;top:50%;left:50%;
  transform:translate(-50%,-50%);font-size:6px;
  color:var(--ink-accent);opacity:.5;
}

/* Meta & Tags */
.ink-meta{display:flex;justify-content:center;flex-wrap:wrap;gap:8px 14px;margin-bottom:10px}
.ink-meta-item{font-size:.95em;color:var(--ink-sub);letter-spacing:.3px;display:flex;align-items:center;gap:3px}
.ink-meta-label{font-weight:600;color:var(--ink-accent);font-size:.95em;opacity:.85;margin-right:3px}
.ink-tags-wrap{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-bottom:14px}
.ink-tag{
  font-size:.63em;color:var(--ink-sub);padding:2px 9px;
  border-radius:10px;background:var(--ink-tag-bg);
  border:1px solid rgba(255,255,255,.08);font-style:italic;
}
.ink-tag::before{content:'#';color:var(--ink-accent);opacity:.6;margin-right:1px}
.ink-header.day .ink-tag{border-color:rgba(0,0,0,.06)}

/* Trích dẫn */
.ink-quote-wrap{
  position:relative;display:inline-block;
  max-width:88%;text-align:left;padding:0 12px;
}
.ink-quote-wrap::before{
  content:'\201C';position:absolute;top:-8px;left:-4px;
  font-family:'Cormorant Garamond',serif;
  font-size:calc(2.8em * var(--ink-fs));
