  line-height:1.8;color:var(--ink-text);opacity:.9;
  transition:font-size .25s;
}
.ink-quote::first-letter{
  font-size:1.55em;font-family:'Cormorant Garamond',serif;
  color:var(--ink-accent);font-weight:600;float:left;
  margin-right:2px;line-height:1;
}
.ink-quote-en{
  display:block;font-family:'Cormorant Garamond',serif;
  font-size:calc(.78em * var(--ink-fs));
  font-style:italic;color:var(--ink-sub);margin-top:5px;
  transition:font-size .25s;
}

.ink-close-quote{
  display:inline-block;
  font-family:'Cormorant Garamond',serif;
  font-size:calc(2.8em * var(--ink-fs));
  font-style:normal;
  font-weight:400;
  color:var(--ink-accent);
  opacity:.3;
  line-height:0;
  margin-left:2px;
  position:relative;
  top:.36em;
  transition:font-size .25s,color .4s;
}

/* ============================================================
