scripts.content:
/*
 * Bảng Phồn Hoa CoT · Phiên bản tinh giản (Bắt buộc mặc định đêm/tiêu đề hồng, tương thích di động, thu hẹp bên trái)
 * [Tối ưu] Bắt toàn bộ nội dung phía trên </thinking>, bất kể có bắt đầu bằng <thinking> hay không
 * Yêu cầu khác: Xóa trang trí viền, tiêu đề tiếp tục tỏa sáng, nội dung thu nhỏ font chữ.
 * [Bản vá] Khoảng cách giữa bảng và văn bản chính đặt thành 0
 * [Sửa đổi] Không có </thinking> thì không đóng: Bắt nội dung thời gian thực khi đang stream
 * [Mới thêm] Ghi nhớ chuyển đổi chủ đề + chuyển đổi thời gian thực: Tối/Sáng + Anh Đào/Oải Hương/Bạc Hà/Pha Lê
 * [Tối ưu hiệu suất] Áp dụng Regex escapeHtml, gỡ rò rỉ bộ nhớ, gỡ reflow vô ích và scroll jitter.
 */
(function () {
  // --- CHỐNG RÒ RỈ BỘ NHỚ ---
